import process from "node:process";
// Generate TypeScript types from the committed JSON Schemas (which are exported from Pydantic).
import { compile } from "json-schema-to-typescript";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schema = JSON.parse(readFileSync(join(root, "schemas/record.schema.json"), "utf8"));
const banner =
  "/* GENERATED by packages/contracts/scripts/gen-types.mjs from schemas/record.schema.json.\n" +
  "   Do not edit. Canonical source: packages/contracts/src/archipelago_contracts/models.py */";
const ts = await compile(schema, "ArchipelagoRecord", {
  bannerComment: banner,
  additionalProperties: false,
  unreachableDefinitions: true,
});
const out = join(root, "generated/types.ts");
if (process.argv.includes("--check")) {
  if (!existsSync(out) || readFileSync(out, "utf8") !== ts) {
    process.stderr.write("generated/types.ts is stale; run npm run gen:types" + "\n");
    process.exit(1);
  }
} else {
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, ts);
}
